begin;
select no_plan();
update public.plans set prova_monthly_exams=null where code='free';
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003601','progress-3601@test.local');
insert into public.families(id,name,created_by,timezone) values('00000000-0000-4000-8000-000000003611','Fixture','00000000-0000-4000-8000-000000003601','Europe/Istanbul');
insert into public.family_members(family_id,user_id) values('00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003601');
insert into public.children(id,family_id,name,grade) values('00000000-0000-4000-8000-000000003621','00000000-0000-4000-8000-000000003611','Fixture',5);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003602','progress-3602@test.local');
insert into public.families(id,name,created_by,timezone) values('00000000-0000-4000-8000-000000003612','Fixture','00000000-0000-4000-8000-000000003602','Europe/Istanbul');
insert into public.family_members(family_id,user_id) values('00000000-0000-4000-8000-000000003612','00000000-0000-4000-8000-000000003602');
insert into public.children(id,family_id,name,grade) values('00000000-0000-4000-8000-000000003622','00000000-0000-4000-8000-000000003612','Fixture',5);


insert into public.study_plans(id,family_id,child_id,subject,grade,plan,updated_at) values
 ('00000000-0000-4000-8000-000000005601','00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003621','Matematik',5,'{"gunler":[{"gun":1},{"gun":2},{"gun":3},{"gun":4}]}','2026-01-01Z');
create function pg_temp.items(d int default 1) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('day',d,'title','Çevre','notes','Kenarları topla','starts_at',date_trunc('day',now())+interval '2 days 15 hours','minutes',20))$$;
create function pg_temp.apply(req uuid,items jsonb,stamp timestamptz default '2026-01-01Z') returns jsonb language sql as $$select public.apply_study_plan_calendar(req,'00000000-0000-4000-8000-000000005601',stamp,items)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select is(jsonb_array_length(pg_temp.apply('00000000-0000-4000-8000-000000005611',pg_temp.items())),1,'selected day applies');
select is((select count(*)::int from public.events),1,'one selected day creates one event');
select is((select notes from public.events),'Kenarları topla','editable activity kept as event notes');
select is((select status from public.study_plans where id='00000000-0000-4000-8000-000000005601'),'approved','explicit apply approves plan');
select is(jsonb_array_length(pg_temp.apply('00000000-0000-4000-8000-000000005611',pg_temp.items())),1,'lost response replays original receipt despite revision change');
select is((select count(*)::int from public.events),1,'no duplicate after replay');
select throws_ok($$select pg_temp.apply('00000000-0000-4000-8000-000000005611',pg_temp.items(2))$$,'P0001','request_conflict','changed payload cannot reuse receipt');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2))$$,'P0001','plan_changed','old snapshot blocked');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(),(select updated_at from public.study_plans limit 1))$$,'P0001','plan_day_applied','same day cannot be applied by another request');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(9),(select updated_at from public.study_plans limit 1))$$,'P0001','plan_invalid','source day must exist');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2)||pg_temp.items(2),(select updated_at from public.study_plans limit 1))$$,'P0001','invalid_input','duplicate selected day rejected');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2)||pg_temp.items(3),(select updated_at from public.study_plans limit 1))$$,'P0001','plan_overlap','overlapping blocks rejected atomically');
select is((select count(*)::int from public.events),1,'failed batch leaves no partial events');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),'[]',(select updated_at from public.study_plans limit 1))$$,'P0001','invalid_input','empty selection blocked');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),jsonb_set(pg_temp.items(2),'{0,minutes}','0'),(select updated_at from public.study_plans limit 1))$$,'P0001','invalid_input','zero duration blocked');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),jsonb_set(pg_temp.items(2),'{0,starts_at}','"infinity"'),(select updated_at from public.study_plans limit 1))$$,'P0001','invalid_input','nonfinite date blocked');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),jsonb_set(pg_temp.items(2),'{0,starts_at}','"2020-01-01T15:00:00Z"'),(select updated_at from public.study_plans limit 1))$$,'P0001','invalid_input','past schedule blocked');
select throws_ok($$insert into public.study_plan_calendar_items(plan_id,day,family_id) values('00000000-0000-4000-8000-000000005601',4,'00000000-0000-4000-8000-000000003611')$$,'42501',null,'cannot forge application link');
delete from public.events;
select is((select count(*)::int from public.study_plan_calendar_items where event_id is null),1,'deleted event retains application history');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(),(select updated_at from public.study_plans limit 1))$$,'P0001','plan_day_applied','old plan cannot silently restore deliberately deleted event');
select public.set_study_plan_status('00000000-0000-4000-8000-000000005601','archived');
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2),(select updated_at from public.study_plans limit 1))$$,'P0001','plan_archived','archived plan cannot add events');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003602","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003612","role":"parent"}}',true);
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2))$$,'42501','forbidden','other family blocked');
select is((select count(*)::int from public.study_plan_calendar_items),0,'other family cannot read links');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"device","child_id":"00000000-0000-4000-8000-000000003621"}}',true);
select throws_ok($$select pg_temp.apply(gen_random_uuid(),pg_temp.items(2))$$,'42501','forbidden','child cannot apply plan');
reset role;
select ok(not has_function_privilege('anon','public.apply_study_plan_calendar(uuid,uuid,timestamptz,jsonb)','EXECUTE'),'anonymous blocked');
select * from finish();
rollback;
